<section class="page-heading"><div><div class="breadcrumbs"><span>Workspace</span><span>/</span><span>{roadmapData.roadmapProject ? roadmapData.roadmapProject.key : 'Overview'}</span></div><h1>{roadmapData.roadmapProject ? `${roadmapData.roadmapProject.name} progress` : 'Roadmap overview'}</h1><p>{roadmapData.roadmapProject ? 'A focused view of delivery, deadlines, and recent activity for this project.' : 'A high-level pulse on every project and what needs attention next.'}</p></div><div class="heading-actions">{#if roadmapData.roadmapProject}<button class="button quiet-button" type="button" on:click={() => setView('roadmap')}>All projects</button>{:else if workspace.projectIntelligenceAnalyzing}<button class="button quiet-button" type="button" on:click={cancelProjectIntelligence}>Cancel Luna</button>{:else}<button class="button primary" type="button" on:click={analyzeProjectIntelligence}>Analyze with Luna</button>{/if}<button class="button quiet-button" type="button" on:click={() => loadRoadmap(roadmapData.roadmapProjectId)}>↻ Refresh</button></div></section>
